package com.ejemplo.msb.entity; import jakarta.persistence.*;import java.util.ArrayList;import java.util.List;@Entity @Table(name="programas_educativos") public class EntityB {@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="nombre",nullable=false,length=160)private String nombreB;@OneToMany(mappedBy="entityB",cascade=CascadeType.ALL,orphanRemoval=true)private List<EntityBEntityA> listaConEntityA=new ArrayList<>();public Long getId(){return id;}public void setId(Long id){this.id=id;}public String getNombreB(){return nombreB;}public void setNombreB(String n){nombreB=n;}public List<EntityBEntityA> getListaConEntityA(){return listaConEntityA;}public void setListaConEntityA(List<EntityBEntityA> l){listaConEntityA=l;}public void addDivision(Long id){listaConEntityA.add(new EntityBEntityA(this,id));}}
